/**
 * Subsetted DejaVu Sans, embedded so PDFs can actually render the rupee sign.
 *
 * jsPDF's built-in Helvetica only covers WinAnsi, where U+20B9 (₹) has no glyph
 * — it came out as a stray superscript and threw off right-aligned text widths.
 * Subsetted here to Latin + the handful of symbols the BOQ uses, which keeps
 * both faces to roughly 22 KB each; the module is dynamically imported so it
 * only loads when someone exports a PDF.
 *
 * DejaVu Fonts, Bitstream Vera / Public-domain-derived license — free to use,
 * embed and redistribute. See PDF_FONT_LICENSE.txt.
 *
 * Generated from /usr/share/fonts/truetype/dejavu via fontTools.subset.
 * Do not hand-edit.
 */

export const PDF_FONT_FAMILY = "DejaVuSans";

export const PDF_FONT_REGULAR_BASE64 =
  "";

export const PDF_FONT_BOLD_BASE64 =
  "";
